package com.greenocean.backend;
import com.greenocean.backend.moderation.service.SocialAttribution;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;

@SpringBootTest @ActiveProfiles("test") @org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseQ2ConcurrencyTest extends MigrationTestSupport {
 static final String SCHEMA="qa_q2_race_"+UUID.randomUUID().toString().replace("-","");
 @DynamicPropertySource static void schema(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired SocialAttribution evidence;
 PhaseIFixtures.Actor a,b,c;UUID assessment;
 @BeforeEach void setup(){db.update("INSERT INTO regional_services(country_code,service,status) VALUES('IR','COMMUNITY','AVAILABLE') ON CONFLICT(country_code,service) DO UPDATE SET status='AVAILABLE'");a=admin();b=admin();c=admin();var owner=PhaseIFixtures.member(db,users,tokens);UUID post=UUID.randomUUID();db.update("INSERT INTO posts(id,author_id,body,is_anonymous,status) VALUES(?,?,'Synthetic concurrency evidence',TRUE,'UNDER_REVIEW')",post,owner.id());assessment=db.queryForObject("INSERT INTO social_assessments(post_id,revision,policy_version,outcome,reason_code) VALUES(?,1,'synthetic-q2','HOLD_FOR_REVIEW','CONTEXT_REVIEW') RETURNING id",UUID.class,post);}
 PhaseIFixtures.Actor admin(){var actor=PhaseIFixtures.member(db,users,tokens);db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='ADMIN'",actor.id());db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",actor.session());return actor;}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 List<Object> race(Supplier<?> first,Supplier<?> second)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();try{return first.get();}catch(RuntimeException ex){return ex;}});var y=pool.submit(()->{start.await();try{return second.get();}catch(RuntimeException ex){return ex;}});start.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 Object approve(PhaseIFixtures.Actor actor,UUID id){evidence.approve(actor.id(),actor.session(),id,1);return "APPROVED";}
 UUID request(){return evidence.request(a.id(),a.session(),assessment,1,"PRIVACY_COMPLAINT");}
 @Test void competingIndependentApprovalsHaveOneWinner()throws Exception{UUID id=request();var r=race(()->approve(b,id),()->approve(c,id));assertThat(r.stream().filter("APPROVED"::equals).count()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM audit_logs WHERE entity_id=? AND action='SOCIAL_ATTRIBUTION_APPROVED'",Integer.class,assessment)).isEqualTo(1);}
 @Test void oneUseGrantCannotBeConsumedTwiceAcrossConnections()throws Exception{UUID id=request();approve(b,id);var r=race(()->evidence.reveal(a.id(),a.session(),assessment,id),()->evidence.reveal(a.id(),a.session(),assessment,id));assertThat(r.stream().filter(Map.class::isInstance).count()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM audit_logs WHERE entity_id=? AND action='SOCIAL_IDENTITY_REVIEW'",Integer.class,assessment)).isEqualTo(1);}
 @Test void revokeAndReadSerializeWithNoPostRevocationReplay()throws Exception{UUID id=request();approve(b,id);var r=race(()->evidence.reveal(a.id(),a.session(),assessment,id),()->{evidence.revoke(b.id(),b.session(),id);return "REVOKED";});assertThat(r).contains("REVOKED");long observed=r.stream().filter(Map.class::isInstance).count();assertThat(db.queryForObject("SELECT count(*) FROM audit_logs WHERE entity_id=? AND action='SOCIAL_IDENTITY_REVIEW'",Long.class,assessment)).isEqualTo(observed);assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),assessment,id)).isInstanceOf(RuntimeException.class);}
 @Test void roleLossAndReadDoNotDeadlockOrRestoreTheGrant()throws Exception{UUID id=request();approve(b,id);var r=race(()->evidence.reveal(a.id(),a.session(),assessment,id),()->{db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='ADMIN')",b.id());return "ROLE_REVOKED";});assertThat(r).contains("ROLE_REVOKED");assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM social_attribution_requests WHERE id=?",Boolean.class,id)).isTrue();assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),assessment,id)).isInstanceOf(RuntimeException.class);}
}
